def kthCrossDistance(a, b, k):
    from bisect import bisect_left, bisect_right
    sb = sorted(b)
    hi = max(max(a) - sb[0], sb[-1] - min(a), 0)

    def count(d):
        return sum(bisect_right(sb, x + d) - bisect_left(sb, x - d) for x in a)

    lo = 0
    while lo < hi:
        mid = (lo + hi) // 2
        if count(mid) >= k:
            hi = mid
        else:
            lo = mid + 1
    return lo
